// Build2 diagnostic override is native, opt-in, expiring and never changes saved Production task options.
BOOL diagnostic = KGLocationDiagnosticsEnabled() && [_task.name isEqualToString:@"karigo-captain-active-work-location"];
if (diagnostic) { distance = 0; interval = 0; }
NSTimeInterval elapsed = [newestLocation.timestamp timeIntervalSinceDate:oldestLocation.timestamp];
BOOL timePassed = elapsed >= interval / 1000.0, distancePassed = _deferredDistance >= distance;
KGLocationRecord(@"BATCH_GATE", @{@"buffered": @(_deferredLocations.count), @"background": @YES, @"diagnosticDeferral": @(diagnostic), @"elapsedSeconds": @(MAX(0,elapsed)), @"distanceBucket": @(MIN(20, floor(MAX(0,_deferredDistance)/50.0))), @"timePassed": @(timePassed), @"distancePassed": @(distancePassed), @"ready": @(timePassed && distancePassed), @"reason": !distancePassed ? @"WAIT_DISTANCE" : !timePassed ? @"WAIT_TIME" : @"BATCH_READY"});
return timePassed && distancePassed;

- (void)locationManagerDidChangeAuthorization:(CLLocationManager *)manager
{
  CLAuthorizationStatus status = manager.authorizationStatus;
  if (status == kCLAuthorizationStatusDenied || status == kCLAuthorizationStatusRestricted) {
    KGLocationRecord(@"NATIVE_ERROR", @{@"denied": @(status == kCLAuthorizationStatusDenied), @"restricted": @(status == kCLAuthorizationStatusRestricted), @"reason": status == kCLAuthorizationStatusRestricted ? @"AUTHORIZATION_RESTRICTED" : @"AUTHORIZATION_DENIED"});
  }
}

